svoya-versiya.js:
const facts = [
  "Осьминог видит кожей.",
  "Улитка может спать три года.",
  "У жирафа синий язык.",
  "Коровы заводят лучших друзей.",
  "Пингвины дарят камушки.",
];

const factText = document.querySelector("#fact");
const button = document.querySelector("#next-fact");

button.addEventListener("click", function () {
  const index = Math.floor(Math.random() * facts.length);
  factText.textContent = facts[index];
});

